{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Edaravone, the closest pyrazolone analogue with the same N-phenyl and C-methyl pyrazolone core, has an absolute oral bioavailability of 57.3% in healthy adults, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Clobazam, an N-aryl heterocycle with high absorption, has 90–100% absolute oral bioavailability in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Meclofenamate, an N-arylanthranilic acid, has human oral bioavailability above 85%, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Roquinimex, which shares N-methyl/N-phenyl amide-like features, shows complete oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Sulphinpyrazone, a diphenylpyrazolidinedione, has 90% absolute oral bioavailability in volunteers, supporting high F for the N-phenylpyrazolone query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues, including the closest pyrazolone edaravone (F≈57%), show oral bioavailability well above 20%; no affirmative threshold-relevant evidence supports F<20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "Morgan similarities are modest (0.22–0.33), so transferability is limited.",
    "Potential first-pass metabolism of the methylamino substituent is not directly captured by the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

